namespace ghidra.file.jad;






using ghidra.framework;
using ghidra.framework;

/**
 * Wrapper class for JAD, a JAva Decompiler.
 */
public class JadProcessWrapper {

	public bool shouldDecompileDeadCode = true;
	public bool shouldInsertNewLineBeforeOpeningBrace = false;
	public bool shouldOutputFieldsBeforeMethods = true;
	public bool shouldOutputSpaceBetweenKeywords = true;
	public bool shouldOverwriteOutputFiles = true;
	public bool shouldRestoreDirectoryStructure = false;
	public bool shouldUseTabsForIndentation = true;
	public bool verbose = false;

	public Radix radix = Radix.SIXTEEN;
	public string outputFileExtension = "java";
	public File outputDirectory;

	private File file;

	public JadProcessWrapper(File file) {
		this.file = file;
	}

	public File getInputDirectory() {
		return file;
	}

	public File getWorkingDirectory() {
		if (file.isDirectory()) {
			return file;
		}
		return file.getParentFile();
	}

	public string[] getCommands()
    {

		List<string> list = new();

		list.add(getJadPath());

		if (shouldDecompileDeadCode) {
			list.add("-dead");
		}

		if (shouldOutputFieldsBeforeMethods) {
			list.add("-ff");
		}

		if (!shouldInsertNewLineBeforeOpeningBrace) {
			list.add("-nonlb");
		}

		if (shouldOverwriteOutputFiles) {
			list.add("-o");
		}

		if (shouldRestoreDirectoryStructure) {
			list.add("-r");
		}

		list.add("-radix" + radix.toString());

		if (outputFileExtension != null) {
			list.add("-s" + outputFileExtension);
		}

		if (shouldOutputSpaceBetweenKeywords) {
			list.add("-space");
		}

		if (shouldUseTabsForIndentation) {
			list.add("-t");
		}

		if (verbose) {
			list.add("-v");
		}

		if (file.isDirectory()) {
			list.add(file.getAbsolutePath() + "/*.class");
		}
		else {
			list.add(file.getAbsolutePath());
		}

		return list.toArray(new string[list.size()]);
	}

	private static string getJadPath()
    {
		File jadExecutableFile =
			Application.getOSFile((Platform.CURRENT_PLATFORM == Platform.WIN_X86_32 ||
				Platform.CURRENT_PLATFORM == Platform.WIN_X86_64) ? "jad.exe" : "jad");

		string jadPath = jadExecutableFile.getAbsolutePath();
		return jadPath;
	}

	/**
	 * A cached check for the presence of the external JAD executable.
	 * 
	 * @return boolean if the executable, for the current platform, is present
	 */
	public static bool isJadPresent() {
		return JADPresentHolder.JAD_PRESENT;
	}

	static class JADPresentHolder {
		static readonly bool JAD_PRESENT = isJadPresent();

		static bool isJadPresent() {
			try {
				string path = getJadPath();
				if (path != null) {
					return true;
				}
			}
			catch (IOException ioe) {
				// fall thru
			}
			return false;
		}
	}

}
